import numpy as np

rng = np.random.default_rng(0)
X_train = rng.normal([50, 3], [10, 1], size=(80, 2))
X_test = rng.normal([50, 3], [10, 1], size=(20, 2)) + [5, 0]

def fit_scaler(X_train):
    return X_train.mean(axis=0), X_train.std(axis=0)

def transform(X, mu, sd):
    return (X - mu) / sd
